cd /home/dev/garden && python3 << 'EOF'
import json
base='bench/results/2026-10-12/m1-ngram/replay'
def load(p):
    rows=[]
    for l in open(p):
        if l.strip(): rows.append(json.loads(l))
    return rows
a=load(f'{base}/A-prod/requests.jsonl')
o=load(f'{base}/off-prod/requests.jsonl')
for phase in ['single-agent','single-mem','dual-agent','dual-mem']:
    arows=[r for r in a if r['phase']==phase and r['fg_bg']=='fg']
    orows={ (r['id'],r['role']): r for r in o if r['phase']==phase and r['fg_bg']=='fg'}
    same=0; n=0
    for r in arows:
        ok=orows.get((r['id'],r['role']))
        n+=1
        if ok is not None and ok.get('out_sha256')==r.get('out_sha256'):
            same+=1
    print(phase, same, '/', n)
EOF

